import numpy as np
np.set_printoptions(linewidth=220, precision=3, suppress=True)
W = dict(np.load('weights.npz'))

def rsv(A):
    U, s, Vt = np.linalg.svd(A, full_matrices=False)
    return Vt.T, s

V = {}
for n in ['W_q.0', 'W_k.0', 'W_v.0', 'W_fc.0']:
    V[n], s = rsv(W[n])
    print(n, 'sv', s[:60])
names = list(V)
for k in [20, 30, 40, 60, 80]:
    for i in range(4):
        for j in range(i + 1, 4):
            c = np.linalg.svd(V[names[i]][:, :k].T @ V[names[j]][:, :k], compute_uv=False)
            print(k, names[i], names[j], 'mean cos2 %.3f (rand %.3f)' % ((c ** 2).mean(), k / 384), 'cos:', c[::max(1, k // 10)])

